/**
 * @summary Get all blog articles
 */
export const getGetBlogArticlesUrl = (params?: GetBlogArticlesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/blog?${stringifiedParams}` : `/api/blog`
}

export const getBlogArticles = async (params?: GetBlogArticlesParams, options?: RequestInit): Promise<Article[]> => {

  return customFetch<Article[]>(getGetBlogArticlesUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





